const intent = $json;
const md = `⚠️ *ONE-TIME LIVE TRADE APPROVAL REQUIRED*

` +
`*Intent ID:* \`${intent.intent_id}\`
` +
`*Chain:* \`${intent.chain_id}\`
` +
`*Action:* ${intent.side} ${intent.asset_symbol}
` +
`*Amount:* ${intent.amount_native} (${intent.amount_usd} USD)
` +
`*Digest:* \`${intent.canonical_intent_digest}\`

` +
`⏳ *Expires in 5 minutes.* Click below to approve or deny:`;

const inlineKeyboard = {
  inline_keyboard: [
    [
      { text: '✅ Approve Trade', url: `http://localhost:8000/api/v1/execution/approve/${intent.intent_id}` },
      { text: '❌ Reject', url: `http://localhost:8000/api/v1/execution/reject/${intent.intent_id}` }
    ]
  ]
};

return [{
  json: {
    chat_id: '{{ $env.TELEGRAM_ALERTS_CHAT_ID }}',
    text: md,
    parse_mode: 'Markdown',
    reply_markup: JSON.stringify(inlineKeyboard)
  }
}];
